import { chromium } from 'playwright';

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('https://www.google.com/search?q=Land%C3%A8s+Lewitin+artist+The+Club');
  const results = await page.locator('div.g').all();
  for (const result of results) {
    const text = await result.innerText();
    console.log(text);
    console.log('---');
  }
  await browser.close();
})();

import { chromium } from 'playwright';

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.goto('https://www.duckduckgo.com/?q=Land%C3%A8s+Lewitin+artist+The+Club');
  console.log('Title:', await page.title());
  const results = await page.locator('article, .result, .result__content').all();
  for (const result of results) {
    try {
      const text = await result.innerText();
      console.log(text);
      console.log('---');
    } catch (e) {
      // ignore
    }
  }
  await browser.close();
})();

